import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Files.md","filePath":"manual-en/Files.md","lastUpdated":1785684581000}'),i={name:"manual-en/Files.md"};function n(r,e,d,l,c,p){return a(),s("div",null,[...e[0]||(e[0]=[o('<h3 id="_6-8-files-used-by-pspp" tabindex="-1">6.8 Files Used by PSPP <a class="header-anchor" href="#_6-8-files-used-by-pspp" aria-label="Permalink to &quot;6.8 Files Used by PSPP&quot;">​</a></h3><p>PSPP makes use of many files each time it runs. Some of these it reads, some it writes, some it creates. Here is a table listing the most important of these files:</p><p><strong>command file</strong><strong>syntax file</strong></p><p>These names (synonyms) refer to the file that contains instructions that tell PSPP what to do. The syntax file’s name is specified on the PSPP command line. Syntax files can also be read with <code>INCLUDE</code> (see <a href="./INCLUDE">INCLUDE</a>).</p><p><strong>data file</strong></p><p>Data files contain raw data in text or binary format. Data can also be embedded in a syntax file with <code>BEGIN DATA</code> and <code>END DATA</code>.</p><p><strong>listing file</strong></p><p>One or more output files are created by PSPP each time it is run. The output files receive the tables and charts produced by statistical procedures. The output files may be in any number of formats, depending on how PSPP is configured.</p><p><strong>system file</strong></p><p>System files are binary files that store a dictionary and a set of cases. <code>GET</code> and <code>SAVE</code> read and write system files.</p><p><strong>portable file</strong></p><p>Portable files are files in a text-based format that store a dictionary and a set of cases. <code>IMPORT</code> and <code>EXPORT</code> read and write portable files.</p>',12)])])}const h=t(i,[["render",n]]);export{m as __pageData,h as default};
